import { formatNumber, t } from './i18n.js';
const escape = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const number = (value) => formatNumber(value);
export const studio = { tab: 'text', draft: 'Shell 120 × 80 × 35 mm, wall 2 mm, radius 8 mm, glossy ABS', proposal: null, previous: null, imported: null, source: 'parametric', photo: null, photoName: '', message: '', busy: false };

export function renderWorkspace({ project, wall, properties, exploded, transparent }) {
  const imported = studio.source === 'imported';
  return `<section class="cad-workspace card" aria-label="Modelling workspace">
    <div class="cad-toolbar"><div class="workspace-title"><span class="live-dot"></span><strong>Design studio</strong><span class="version-tag">LOCAL DEMO</span></div><div class="workspace-tools"><button class="button secondary compact" data-view="summary">Requirements</button><button class="button primary compact" data-view="part">Prepare project →</button></div></div>
    <div class="cad-grid">
      <aside class="model-browser"><div class="panel-heading">PROJECT EXPLORER <span>01</span></div><div class="assembly-name">◇ Electronic enclosure</div><button class="tree-item ${!imported ? 'selected' : ''}" data-model-source="parametric"><span>▧</span><span>Parametric shells<small>Editable geometry</small></span><span class="tree-status">2</span></button><div class="tree-children"><span>⌑ Front shell</span><span>⌑ Rear shell</span></div>${studio.imported ? `<button class="tree-item ${imported ? 'selected' : ''}" data-model-source="imported"><span>◇</span><span><span data-user-content>${escape(studio.imported.file_name)}</span><small>Mesh · this session only</small></span></button>` : ''}<div class="browser-divider"></div><div class="panel-heading">PROJECT DATA</div><button class="tree-link" data-view="brief">▤ Customer request <span>↗</span></button><button class="tree-link" data-view="part">◈ Materials and constraints <span>↗</span></button><button class="tree-link" data-view="machines">▱ Press inventory <span>↗</span></button><div class="browser-divider"></div><div class="panel-heading">DEVELOPMENT PATH</div><ol class="design-path"><li class="current"><span>1</span><div>Part geometry<small>Demo capability</small></div></li><li><span>2</span><div>Mouldability analysis<small>Planned module</small></div></li><li><span>3</span><div>Mould, press and costs<small>Planned module</small></div></li><li><span>4</span><div>Process simulation<small>Planned module</small></div></li></ol><div class="browser-note">Future modules will share geometry, requirements and traceable assumptions.</div></aside>
      <div class="model-stage"><div class="stage-top"><span class="stage-name">${imported ? 'IMPORTED MESH' : 'PARAMETRIC ASSEMBLY'} <span>· mm</span></span><span class="stage-state">${imported ? 'Units confirmed · surface not verified' : 'Preliminary geometry'}</span></div><div class="viewport-wrap"><div class="viewport-actions"><div class="view-buttons">${[['iso', 'ISO'], ['front', 'Front'], ['rear', 'Rear'], ['side', 'Side']].map(([view, label]) => `<button class="button secondary compact" data-concept-camera="${view}">${label}</button>`).join('')}</div><div class="view-buttons"><button class="button secondary compact" id="concept-explode" aria-pressed="${exploded}" ${imported ? 'disabled' : ''}>Exploded view</button><button class="button secondary compact" id="concept-transparent" aria-pressed="${transparent}">Transparency</button></div></div><div class="concept-viewport" id="concept-viewport"><p class="concept-loading">Preparing model…</p></div><div class="viewport-label"><span class="axis-label"><i>X</i><i>Y</i><i>Z</i></span><span>Drag to orbit · scroll to zoom</span></div></div><div class="stage-bottom"><div class="preview-variants"><span>WALL <small>Preliminary comparison</small></span><div>${project.part.wall_options_mm.map((value) => `<button class="button secondary compact ${value === wall ? 'selected' : ''}" data-preview-wall="${value}" aria-pressed="${value === wall}" ${imported ? 'disabled' : ''}>${number(value)} mm</button>`).join('')}</div></div><div class="concept-metrics" id="concept-metrics"></div></div><div class="stage-footer"><span>${imported ? 'Mesh in memory · reload the file after restart' : 'Clips, seals and functional details are not modelled'}</span><button class="button secondary compact" id="concept-download" disabled>↓ Export OBJ</button></div></div>
      <aside class="creation-panel"><div class="panel-heading">CREATE YOUR PART <span>↗</span></div><h2>Start with an idea.</h2><p class="panel-intro">Describe the demo shell, open a mesh or add a reference.</p><div class="source-tabs" role="tablist" aria-label="Part input">${[['text', 'Describe'], ['file', '3D file'], ['photo', 'Photo']].map(([key, label]) => `<button id="source-tab-${key}" role="tab" aria-selected="${studio.tab === key}" aria-controls="source-panel-${key}" data-source-tab="${key}" tabindex="${studio.tab === key ? 0 : -1}">${label}</button>`).join('')}</div>
      <section class="source-panel" id="source-panel-text" role="tabpanel" aria-labelledby="source-tab-text" ${studio.tab !== 'text' ? 'hidden' : ''}><div class="local-label">LOCAL PARAMETRIC COMMANDS</div><form id="description-form"><label for="part-description">What would you like to create?</label><textarea id="part-description" maxlength="4000" placeholder="Shell 140 × 90 × 40 mm, wall 2 mm, radius 10 mm, ABS…">${escape(studio.draft)}</textarea><p class="source-help">Local commands support dimensions, wall, radius, ABS/PC-ABS/PP/PE and finish. Conversational AI is not yet integrated.</p><button class="button primary" type="submit">Prepare change <span>↗</span></button></form><div id="description-proposal" aria-live="polite"></div><button class="text-button undo-command" id="undo-description" ${studio.previous ? '' : 'hidden'}>↶ Undo last text change</button></section>
      <section class="source-panel" id="source-panel-file" role="tabpanel" aria-labelledby="source-tab-file" ${studio.tab !== 'file' ? 'hidden' : ''}><label for="mesh-units">File coordinate units</label><select id="mesh-units"><option value="">Select units</option><option value="mm">Millimetres</option><option value="cm">Centimetres</option><option value="m">Metres</option><option value="in">Inches</option></select><label class="upload-zone" for="mesh-file"><span>◇</span><strong>Open a 3D model</strong><small>OBJ / STL · max 12 MB · 100,000 triangles</small><input id="mesh-file" type="file" accept=".obj,.stl"></label><p class="source-help">View mesh bounds without changing the brief. STEP and CAD solids require the planned CAD module.</p>${studio.imported ? `<div class="asset-info"><span data-user-content>${escape(studio.imported.file_name)}</span><small>${t('{count} triangles · source {unit}', { count: number(studio.imported.triangle_count), unit: escape(studio.imported.source_units) })}</small></div><button class="text-button" id="adopt-mesh-dimensions">Use these bounds in the brief</button>` : ''}</section>
      <section class="source-panel" id="source-panel-photo" role="tabpanel" aria-labelledby="source-tab-photo" ${studio.tab !== 'photo' ? 'hidden' : ''}><label class="upload-zone" for="photo-file"><span>▣</span><strong>Add a photo</strong><small>JPG / PNG / WebP · max 8 MB</small><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label>${studio.photo ? `<figure class="photo-reference"><img src="${escape(studio.photo)}" alt="User-uploaded reference photo"><figcaption><span data-user-content>${escape(studio.photoName)}</span> · <span>this session only</span></figcaption></figure><button class="text-button" id="remove-photo">Remove reference</button>` : ''}<p class="source-help">Photos are visual references. Reconstruction needs a known dimension and multiple views; internal features, tolerances and material must be specified.</p><div class="feature-note">Automatic image reconstruction is a planned module.</div></section>
      <p class="studio-message" id="studio-message" role="status">${escape(studio.message)}</p><details class="properties-section" ${studio.tab === 'properties' ? 'open' : ''}><summary>Demo shell properties <span>⌄</span></summary><div class="compact-properties">${properties}</div></details><div class="next-operation"><div class="local-label">AFTER GEOMETRY</div><strong>Prepare mouldability inputs</strong><p>Define material grade, requirements and surfaces before a mould concept.</p><button class="text-button" data-view="part">Open technical requirements →</button></div></aside>
    </div><div class="cad-status"><span><span class="live-dot"></span> Local processing</span><span>${imported ? 'Imported mesh' : 'Parametric model'} <span class="status-separator">/</span> No engineering validation performed</span><span>mm <span class="status-separator">/</span> WebGL</span></div>
  </section>`;
}
